import { cp, mkdir, mkdtemp, readFile, rm, symlink, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from 'node:util';
import { FaceModelEmitter, WorkspaceAnalyzer } from '@deepseek-ai/dsh-typert-generator';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const { values } = parseArgs({ options: { write: { type: 'boolean' }, check: { type: 'boolean' }, 'out-dir': { type: 'string' } } });
if (values.write && values.check) throw new Error('Use either --write or --check');
const output = resolve(root, values['out-dir'] ?? '.artifacts/native-typert');
const scratch = await mkdtemp(join(tmpdir(), 'dsh-flow-typert-'));
const native = resolve(root, 'packages/dsh-flow/src/native');
const json = (path: string, value: unknown) => writeFile(path, `${JSON.stringify(value, null, 2)}\n`);

try {
  await symlink(resolve(root, 'node_modules'), join(scratch, 'node_modules'), 'dir');
  const paths = {
    '@deepseek-ai/dsh-typert-protocol': [join(scratch, 'packages/protocol/src/index.d.ts')],
    '@deepseek-ai/dsh-util-values': [join(scratch, 'packages/util-values/src/index.d.ts')],
  };
  const compilerOptions = {
    target: 'ES2022', module: 'NodeNext', moduleResolution: 'NodeNext', strict: true,
    noUncheckedIndexedAccess: true, exactOptionalPropertyTypes: true, noImplicitOverride: true,
    skipLibCheck: true, esModuleInterop: true, types: ['node'], lib: ['ES2023', 'DOM', 'ESNext.Disposable'],
    jsx: 'react-jsx', rootDir: 'src', outDir: 'lib/types', paths,
  };
  for (const [folder, name] of [['protocol', '@deepseek-ai/dsh-typert-protocol'], ['util-values', '@deepseek-ai/dsh-util-values']] as const) {
    const resolver = name === '@deepseek-ai/dsh-util-values' ? createRequire(require.resolve('@deepseek-ai/dsh-typert-protocol')) : require;
    const manifestPath = resolver.resolve(`${name}/package.json`);
    const manifest = JSON.parse(await readFile(manifestPath, 'utf8')) as { types: string };
    const destination = join(scratch, 'packages', folder);
    await mkdir(destination, { recursive: true });
    await cp(dirname(resolve(dirname(manifestPath), manifest.types)), join(destination, 'src'), { recursive: true });
    await json(join(destination, 'package.json'), { name, type: 'module', exports: { '.': { types: './src/index.d.ts', default: './src/index.js' } } });
    await json(join(destination, 'tsconfig.json'), { compilerOptions: { ...compilerOptions, composite: true }, include: ['src/**/*.d.ts'] });
  }
  const flow = join(scratch, 'packages/dsh-flow');
  await mkdir(flow, { recursive: true });
  await cp(resolve(root, 'packages/dsh-flow/src'), join(flow, 'src'), { recursive: true });
  await writeFile(join(flow, 'src/native/generator-face.ts'), "export { FlowDashboardRemote } from './host.js';\nexport type * from './protocol.js';\n");
  await json(join(flow, 'package.json'), {
    name: 'dsh-flow', type: 'module', exports: {
      '.': { types: './lib/types/native/generator-face.d.ts', default: './lib/native/generator-face.js' },
      './native/protocol': { types: './lib/types/native/protocol.d.ts', default: './lib/native/protocol.js' },
    },
  });
  await json(join(flow, 'tsconfig.json'), { compilerOptions, include: ['src/**/*.ts'] });
  await json(join(scratch, 'tsconfig.host.json'), {
    compilerOptions, files: [], references: ['dsh-flow', 'protocol', 'util-values'].map(folder => ({ path: `./packages/${folder}` })),
  });
  const model = new WorkspaceAnalyzer({ root: scratch, packages: ['dsh-flow'], faces: ['host'], checkDiagnostics: false }).analyze();
  const face = model.faces[0];
  if (!face) throw new Error('No host FaceModel generated');
  const emitted = new FaceModelEmitter(face).emit('dsh-flow');
  if (!emitted.remote) throw new Error('No Native Remote contribution generated');
  const artifacts = {
    'typert.host.js': emitted.js, 'typert.host.d.ts': emitted.dts,
    'typert.remote-client.js': emitted.remote.js, 'typert.remote-client.d.ts': emitted.remote.dts,
  };
  await mkdir(output, { recursive: true });
  await json(join(output, 'model.json'), model);
  const mismatches: string[] = [];
  for (const [name, generated] of Object.entries(artifacts)) {
    const content = generated
      .replace(/^\/\* Generated by @deepseek-ai\/dsh-typert-generator from (?:the Host )?FaceModel — do not edit\. \*\/\n/, '')
      .replace(/^\/\/# sourceMappingURL=typert\.remote-client\.d\.ts\.map\r?\n?/m, '');
    await writeFile(join(output, name), content);
    if (values.write) await writeFile(join(native, name), content);
    if (values.check && content !== await readFile(join(native, name), 'utf8')) mismatches.push(name);
  }
  if (mismatches.length) throw new Error(`Generated artifacts differ: ${mismatches.join(', ')}. Inspect ${output}`);
  console.log(`Native Typert ${values.write ? 'written' : values.check ? 'verified' : 'generated'}: ${output}`);
} finally {
  await rm(scratch, { recursive: true, force: true });
}
